def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last = history[-1][0]
    opp_last = history[-1][1]

    opp = [h[1] for h in history]
    op_d = opp.count('D')
    op_c = n - op_d

    if op_c == 0:
        return 'D'

    if n >= 6 and op_d >= n - 1:
        return 'D'
    if n >= 10 and op_d >= n - 2:
        return 'D'

    if n >= 96 and op_d == 0 and opp_last == 'C':
        return 'D'

    win = 8 if n >= 8 else n
    recent_d = 0
    for i in range(n - win, n):
        if opp[i] == 'D':
            recent_d += 1

    if win >= 2 and recent_d >= win - 1:
        return 'D'

    if n >= 16:
        recent_d16 = 0
        for i in range(n - 16, n):
            if opp[i] == 'D':
                recent_d16 += 1
        if recent_d16 >= 10:
            return 'D'

    if op_d * 3 > n and recent_d >= 2:
        return 'D'

    streak = 0
    i = n - 1
    while i >= 0:
        if opp[i] == opp_last:
            streak += 1
        else:
            break
        i -= 1

    if opp_last == 'D':
        if my_last == 'D' and streak >= 3 and op_c > op_d:
            return 'C'
        if my_last == 'D' and streak >= 2 and op_c > op_d:
            return 'C'
        if streak >= 2:
            return 'D'
        if op_d * 2 >= n:
            return 'D'
        if my_last == 'D':
            return 'C'
        return 'D'

    if op_d * 2 > n:
        return 'D'

    if op_c * 5 >= n * 4:
        return 'C'

    if recent_d >= 3:
        return 'D'

    return 'C'
